// =======================================================================
// CAPACITY BY ORBIT CLASS
// -----------------------------------------------------------------------
// A donut chart built from 3 data points. Generated by
// AE Graph Forge on 2026-07-26 02:52.
//
// X: Orbit_Type
// Y: -
//
// Run this in After Effects: File > Scripts > Run Script File...
// It builds one new composition and does not touch anything else in
// your project. Every look property is wired to MASTER_CONTROLS --
// scrub "Progress" to drive the reveal, and use the other controls
// on that null to re-art-direct the whole graph after the build.
// =======================================================================

(function buildChart() {

    app.beginUndoGroup("Build SAT_Capacity_Share");

    try {


    // ---------------------------------------------------------------
    // CONFIG
    // ---------------------------------------------------------------
    var COMP_NAME = "SAT_Capacity_Share";
    var COMP_W = 1920, COMP_H = 1080, COMP_FPS = 30, COMP_DUR = 14;
    var PROGRESS_START_T = 1;
    var PROGRESS_END_T   = 12;

    var PLOT_L = 220, PLOT_R = 1800;
    var PLOT_T = 170, PLOT_B = 860;

    var N = 3;

    var BG_COLOR    = [0.0000, 0.0000, 0.0000];
    var GRID_COLOR  = [0.2500, 0.2500, 0.2700];
    var AXIS_COLOR  = [0.7500, 0.7800, 0.8200];
    var TITLE_COLOR = [0.9500, 0.9500, 0.9500];
    var SUB_COLOR   = [0.6500, 0.6500, 0.6800];
    var CAP_COLOR   = [0.6000, 0.6300, 0.6700];

    // ---------------------------------------------------------------
    // PIXEL-SPACE GEOMETRY (precomputed from the CSV)
    // ---------------------------------------------------------------
    // VERTICES / tangents form a Catmull-Rom-smoothed bezier path:
    //     out[i] = (P[i+1] - P[i-1]) / 6,  in[i] = -out[i]
    // ARC is the cumulative length fraction at each vertex, so a
    // Trim Paths reveal stays in step with a uniform one-point-at-a-time
    // sweep of the Progress slider.


    // ---------------------------------------------------------------
    // SHARED HELPERS
    // ---------------------------------------------------------------
    function joinExpr(lines) {
        return lines.join("\n");
    }

    // ---------------------------------------------------------------------------
    // Shape property lookup.
    //
    // After Effects invalidates a stored shape-property reference as soon as more
    // items are added to the same vector group, so a handle grabbed mid-build goes
    // stale even though the layer is still perfectly valid. Nothing below ever
    // caches a property object: every vector property is given a name at creation
    // time and looked back up by name at the moment it is used.
    // ---------------------------------------------------------------------------
    function vgroup(layer, groupName) {
        var contents = layer.property("Contents");
        for (var i = 1; i <= contents.numProperties; i++) {
            if (contents.property(i).name === groupName) return contents.property(i);
        }
        return null;
    }

    function vprop(layer, groupName, propName) {
        var g = vgroup(layer, groupName);
        if (g === null) return null;
        var c = g.property("Contents");
        for (var i = 1; i <= c.numProperties; i++) {
            if (c.property(i).name === propName) return c.property(i);
        }
        return null;
    }

    function addSlider(layer, name, value) {
        var fx = layer.property("Effects").addProperty("ADBE Slider Control");
        fx.name = name;
        fx.property("Slider").setValue(value);
        return fx;
    }

    function addColor(layer, name, rgb) {
        var fx = layer.property("Effects").addProperty("ADBE Color Control");
        fx.name = name;
        fx.property("Color").setValue([rgb[0], rgb[1], rgb[2], 1]);
        return fx;
    }

    function spanLayer(layer) {
        layer.inPoint = 0;
        layer.outPoint = comp.duration;
        return layer;
    }

    // Vertices are precomputed in COMPOSITION pixel space, so the layer and its
    // vector group both need an identity transform or the graph lands offset from
    // the text and gridlines. Setting anchor and position to the same point gives
    // that identity while leaving the pivot at comp centre, so scaling or rotating
    // the finished graph behaves the way you would expect.
    function centerShapeLayer(layer, groupName) {
        var cx = COMP_W / 2;
        var cy = COMP_H / 2;
        var tr = layer.property("Transform");
        tr.property("Anchor Point").setValue([cx, cy]);
        tr.property("Position").setValue([cx, cy]);
        var g = vgroup(layer, groupName);
        if (g !== null) {
            var gt = g.property("Transform");
            gt.property("Anchor Point").setValue([cx, cy]);
            gt.property("Position").setValue([cx, cy]);
        }
        return layer;
    }

    function setFont(td) {
        var fontCandidates = ["Arial-BoldMT", "Arial-Bold", "Arial,Bold", "ArialMT", "Arial"];
        for (var f = 0; f < fontCandidates.length; f++) {
            try { td.font = fontCandidates[f]; break; } catch (e) {}
        }
    }

    function makeText(str, size, color, pos, justify) {
        var t = spanLayer(comp.layers.addText(str));
        var td = t.property("Source Text").value;
        td.fontSize = size;
        td.fillColor = color;
        setFont(td);
        try {
            if (justify === "left") {
                td.justification = ParagraphJustification.LEFT_JUSTIFY;
            } else if (justify === "right") {
                td.justification = ParagraphJustification.RIGHT_JUSTIFY;
            } else {
                td.justification = ParagraphJustification.CENTER_JUSTIFY;
            }
        } catch (e) {}
        t.property("Source Text").setValue(td);
        t.property("Transform").property("Position").setValue(pos);
        t.property("Transform").property("Anchor Point").setValue([0, 0]);
        return t;
    }

    function addHGridline(y, w) {
        var g = spanLayer(comp.layers.addSolid(GRID_COLOR, "Gridline", Math.max(1, Math.round(w)), 2, 1));
        g.property("Transform").property("Anchor Point").setValue([0, 0]);
        g.property("Transform").property("Position").setValue([PLOT_L + w / 2, y]);
        g.property("Transform").property("Opacity").setValue(45);
        return g;
    }

    function addVGridline(x, h) {
        var g = spanLayer(comp.layers.addSolid(GRID_COLOR, "Gridline", 2, Math.max(1, Math.round(h)), 1));
        g.property("Transform").property("Position").setValue([x, PLOT_T + h / 2]);
        g.property("Transform").property("Opacity").setValue(45);
        return g;
    }

    function addLegendSwatch(x, y, color) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = "LegendSwatch";
        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "SwatchGroup";
        var rect = group.property("Contents").addProperty("ADBE Vector Shape - Rect");
        rect.name = "SwatchRect";
        rect.property("Size").setValue([20, 20]);
        var fill = group.property("Contents").addProperty("ADBE Vector Graphic - Fill");
        fill.name = "SwatchFill";
        fill.property("Color").setValue(color);
        layer.property("Transform").property("Anchor Point").setValue([0, 0]);
        layer.property("Transform").property("Position").setValue([x, y]);
        return layer;
    }

    function addLegendCircle(x, y, diameter) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = "LegendCircle";
        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "CircleGroup";
        var ellipse = group.property("Contents").addProperty("ADBE Vector Shape - Ellipse");
        ellipse.name = "CircleShape";
        ellipse.property("Size").setValue([diameter, diameter]);
        var stroke = group.property("Contents").addProperty("ADBE Vector Graphic - Stroke");
        stroke.name = "CircleStroke";
        stroke.property("Color").setValue(AXIS_COLOR);
        stroke.property("Stroke Width").setValue(1.5);
        layer.property("Transform").property("Anchor Point").setValue([0, 0]);
        layer.property("Transform").property("Position").setValue([x, y]);
        return layer;
    }

    function buildLineLayer(name, vertices, inT, outT, color, strokeWidth, closed) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = name;

        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "LineGroup";

        var pathProp = group.property("Contents").addProperty("ADBE Vector Shape - Group");
        pathProp.name = "LinePath";

        var shape = new Shape();
        shape.vertices = vertices;
        shape.inTangents = inT;
        shape.outTangents = outT;
        shape.closed = (closed === true);
        pathProp.property("Path").setValue(shape);

        var stroke = group.property("Contents").addProperty("ADBE Vector Graphic - Stroke");
        stroke.name = "LineStroke";
        stroke.property("Color").setValue(color);
        stroke.property("Stroke Width").setValue(strokeWidth);
        stroke.property("Line Cap").setValue(2);
        stroke.property("Line Join").setValue(2);

        var trim = group.property("Contents").addProperty("ADBE Vector Filter - Trim");
        trim.name = "Trim";

        // group construction is finished, so it is now safe to place the layer
        centerShapeLayer(layer, "LineGroup");
        return layer;
    }

    function buildAreaLayer(name, vertices, inT, outT, color, opacity) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = name;
        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "AreaGroup";
        var pathProp = group.property("Contents").addProperty("ADBE Vector Shape - Group");
        pathProp.name = "AreaPath";
        var shape = new Shape();
        shape.vertices = vertices;
        shape.inTangents = inT;
        shape.outTangents = outT;
        shape.closed = true;
        pathProp.property("Path").setValue(shape);
        var fill = group.property("Contents").addProperty("ADBE Vector Graphic - Fill");
        fill.name = "AreaFill";
        fill.property("Color").setValue(color);
        fill.property("Opacity").setValue(opacity);
        centerShapeLayer(layer, "AreaGroup");
        return layer;
    }

    function buildDot(name, diameter, color) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = name;
        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "Dot";
        var ellipse = group.property("Contents").addProperty("ADBE Vector Shape - Ellipse");
        ellipse.name = "DotShape";
        ellipse.property("Size").setValue([diameter, diameter]);
        var fill = group.property("Contents").addProperty("ADBE Vector Graphic - Fill");
        fill.name = "DotFill";
        fill.property("Color").setValue(color);
        // A dot is placed by Position, so its anchor stays at the shape centre and
        // Scale pivots on the dot itself.
        layer.property("Transform").property("Anchor Point").setValue([0, 0]);
        return layer;
    }

    function buildBar(name, w, h, color) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = name;
        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "Bar";
        var rect = group.property("Contents").addProperty("ADBE Vector Shape - Rect");
        rect.name = "BarRect";
        rect.property("Size").setValue([w, h]);
        var fill = group.property("Contents").addProperty("ADBE Vector Graphic - Fill");
        fill.name = "BarFill";
        fill.property("Color").setValue(color);
        // A bar grows from its baseline, so the anchor stays there rather than at
        // comp centre.
        layer.property("Transform").property("Anchor Point").setValue([0, 0]);
        return layer;
    }

    function buildRing(name, radius, thickness, color) {
        var layer = spanLayer(comp.layers.addShape());
        layer.name = name;
        var group = layer.property("Contents").addProperty("ADBE Vector Group");
        group.name = "RingGroup";
        var ellipse = group.property("Contents").addProperty("ADBE Vector Shape - Ellipse");
        ellipse.name = "RingShape";
        ellipse.property("Size").setValue([radius * 2, radius * 2]);
        var stroke = group.property("Contents").addProperty("ADBE Vector Graphic - Stroke");
        stroke.name = "RingStroke";
        stroke.property("Color").setValue(color);
        stroke.property("Stroke Width").setValue(thickness);
        stroke.property("Line Cap").setValue(1);
        var trim = group.property("Contents").addProperty("ADBE Vector Filter - Trim");
        trim.name = "RingTrim";
        layer.property("Transform").property("Anchor Point").setValue([0, 0]);
        return layer;
    }

    function easyEase(prop, idx) {
        var ease = new KeyframeEase(0, 33);
        prop.setTemporalEaseAtKey(idx, [ease], [ease]);
    }

    function buildPlayhead() {
        var ph = spanLayer(comp.layers.addSolid([0.95, 0.95, 0.95], "Playhead", 2,
                           Math.max(1, Math.round(PLOT_B - PLOT_T)), 1));
        ph.property("Transform").property("Opacity").setValue(35);
        return ph;
    }

    // ---------------------------------------------------------------
    // COMP + BACKGROUND
    // ---------------------------------------------------------------
    var comp = app.project.items.addComp(COMP_NAME, COMP_W, COMP_H, 1, COMP_DUR, COMP_FPS);
    comp.openInViewer();
    var bg = spanLayer(comp.layers.addSolid(BG_COLOR, "BG", COMP_W, COMP_H, 1));

    // ---------------------------------------------------------------
    // MASTER_CONTROLS  -- one null drives the entire graph
    // ---------------------------------------------------------------
    var controls = spanLayer(comp.layers.addNull());
    controls.name = "MASTER_CONTROLS";
    addSlider(controls, "Progress", 0);
    addSlider(controls, "Line Weight", 100);
    addSlider(controls, "Grid Width", 100);
    addSlider(controls, "Title Opacity", 100);
    addSlider(controls, "Legend Opacity", 100);
    addSlider(controls, "Playhead Width", 100);
    addSlider(controls, "Ring Thickness", 100);
    addSlider(controls, "Ring Gap", 0);
    addSlider(controls, "Dot Scale", 100);
    addSlider(controls, "Dot Opacity", 100);
    addSlider(controls, "Reveal Softness", 0);
    addSlider(controls, "Grid Opacity", 45);
    addSlider(controls, "Labels Opacity", 100);
    addSlider(controls, "Playhead Opacity", 35);
    addSlider(controls, "Tip Size", 16);

    var progressSlider = controls.property("Effects").property("Progress").property("Slider");
    progressSlider.setValueAtTime(PROGRESS_START_T, 0);
    progressSlider.setValueAtTime(PROGRESS_END_T, 100);
    easyEase(progressSlider, 1);
    easyEase(progressSlider, 2);

    // Re-usable snippets so every layer reads the same rig.
    var GRID_OP_EXPR = joinExpr([
        "var ctrl = thisComp.layer(\"MASTER_CONTROLS\");",
        "ctrl.effect(\"Grid Opacity\")(\"Slider\");"
    ]);
    var LABEL_OP_EXPR = joinExpr([
        "var ctrl = thisComp.layer(\"MASTER_CONTROLS\");",
        "ctrl.effect(\"Labels Opacity\")(\"Slider\");"
    ]);

    // ---------------------------------------------------------------
    // TITLE / SUBTITLE / CAPTION
    // ---------------------------------------------------------------
    makeText("CAPACITY BY ORBIT CLASS", 46, TITLE_COLOR, [PLOT_L, 80], "left");

    // ---------------------------------------------------------------
    // LEGEND
    // ---------------------------------------------------------------
    var sw0 = addLegendSwatch(220, 1020, [0.9500, 0.9500, 0.9500]);
    makeText("MEO", 20, [0.85, 0.85, 0.85], [242, 1027], "left");
    var sw1 = addLegendSwatch(327.56, 1020, [0.4000, 0.8500, 0.9000]);
    makeText("GEO", 20, [0.85, 0.85, 0.85], [349.56, 1027], "left");
    var sw2 = addLegendSwatch(434.02, 1020, [0.9500, 0.7000, 0.3500]);
    makeText("LEO", 20, [0.85, 0.85, 0.85], [456.02, 1027], "left");

    // ---------------------------------------------------------------
    // DONUT SEGMENTS
    // ---------------------------------------------------------------
    var RING_CX = 1010;
    var RING_CY = 515;
    var RING_R = 269.1;
    var RING_W = 118.4;
    var SEG_START = [0,47.53,90.59];
    var SEG_END = [47.53,90.59,100];
    var SEG_AT = [0,33.33,66.67];
    var SEG_COLORS = [[0.9500, 0.9500, 0.9500], [0.4000, 0.8500, 0.9000], [0.9500, 0.7000, 0.3500]];

    for (var g = 0; g < SEG_START.length; g++) {
        var seg = buildRing("SEG_" + g, RING_R, RING_W, SEG_COLORS[g]);
        seg.property("Transform").property("Position").setValue([RING_CX, RING_CY]);
        vprop(seg, "RingGroup", "RingStroke").property("Stroke Width").expression = joinExpr([
            "var ctrl = thisComp.layer(\"MASTER_CONTROLS\");",
            "var base = 118.4;",
            "base * ctrl.effect(\"Ring Thickness\")(\"Slider\") / 100;"
        ]);
        vprop(seg, "RingGroup", "RingTrim").property("Start").expression =
            'var ctrl = thisComp.layer("MASTER_CONTROLS");\n' +
            'var gap = ctrl.effect("Ring Gap")("Slider") * 0.1;\n' +
            'var a = ' + SEG_START[g] + ';\n' +
            'a + gap;';
        vprop(seg, "RingGroup", "RingTrim").property("End").expression =
            'var ctrl = thisComp.layer("MASTER_CONTROLS");\n' +
            'var progress = ctrl.effect("Progress")("Slider");\n' +
            'var gap = ctrl.effect("Ring Gap")("Slider") * 0.1;\n' +
            'var a = ' + SEG_START[g] + ';\n' +
            'var b = ' + SEG_END[g] + ';\n' +
            'var at = ' + SEG_AT[g] + ';\n' +
            'var span = 33.333333;\n' +
            'var hi = Math.max(at + span, at + 0.001);\n' +
            'a + gap + ease(progress, at, hi, 0, Math.max(0, b - a - gap));';
    }

    // slice labels, placed on the ring at each wedge midpoint
    var slab0 = makeText("MEO  47.5%", 20, AXIS_COLOR, [1371.21, 494.95], "left");
    slab0.property("Transform").property("Opacity").expression = joinExpr([
        "var ctrl = thisComp.layer(\"MASTER_CONTROLS\");",
        "var progress = ctrl.effect(\"Progress\")(\"Slider\");",
        "var at = 0;",
        "var span = 33.333333;",
        "linear(progress, at, Math.max(at + span, at + 0.001), 0, 100);"
    ]);
    var slab1 = makeText("GEO  43.1%", 20, AXIS_COLOR, [672.62, 655.06], "right");
    slab1.property("Transform").property("Opacity").expression = joinExpr([
        "var ctrl = thisComp.layer(\"MASTER_CONTROLS\");",
        "var progress = ctrl.effect(\"Progress\")(\"Slider\");",
        "var at = 33.333333;",
        "var span = 33.333333;",
        "linear(progress, at, Math.max(at + span, at + 0.001), 0, 100);"
    ]);
    var slab2 = makeText("LEO  9.4%", 20, AXIS_COLOR, [904.45, 176.41], "right");
    slab2.property("Transform").property("Opacity").expression = joinExpr([
        "var ctrl = thisComp.layer(\"MASTER_CONTROLS\");",
        "var progress = ctrl.effect(\"Progress\")(\"Slider\");",
        "var at = 66.666667;",
        "var span = 33.333333;",
        "linear(progress, at, Math.max(at + span, at + 0.001), 0, 100);"
    ]);

    alert("Built \"" + COMP_NAME + "\" (3 points). Scrub Progress on MASTER_CONTROLS, or play the comp.");

    } catch (err) {
    alert("Build failed: " + err.toString() + "\nLine: " + (err.line || "unknown") + "\nFile: " + (err.fileName || "unknown"));
    throw err;
    } finally {
    app.endUndoGroup();
    }

})();
